select t.n as table_name, r.rolname as role, count(*) as stmts, sum(s.calls)::bigint as calls,
  sum(s.calls) filter (where s.query ~* '^\s*(insert|update|delete|merge|copy|truncate)')::bigint as write_calls
from t join pg_stat_statements s on s.query ~ ('(^|[^A-Za-z0-9_])' || t.n || '([^A-Za-z0-9_]|$)')
join pg_roles r on r.oid=s.userid
group by 1,2 order by 1,2;
